mapper.select:


    p.is_deleted = 0

        AND p.batch_id = #{batchId}


        AND p.trial_id = #{trialId}


        AND p.trial_field_name like concat('%', #{trialFieldName}, '%')


        AND b.crop_type = #{cropType}


        AND b.variety_name like concat('%', #{varietyName}, '%')


order by p.create_time desc

select distinct p.ground_id, p.batch_id, p.trial_id, p.trial_field_name, p.gps_location, p.region from plot_info p
inner join trial_plot_relation r on p.ground_id = r.ground_id and r.is_deleted = 0
p.is_deleted = 0
AND p.batch_id = #{batchId}
AND r.trial_id = #{trialId}
order by p.create_time desc
